-- deep3/g29: deep pass 3, 2026-09-24. Python door (connect/db.py), read-only SELECT/WITH only, QUERY_TAG 'deep3-2026-09-24'.
-- Every connection first ran: ALTER SESSION SET STATEMENT_TIMEOUT_IN_SECONDS = 300; ALTER SESSION SET QUERY_TAG = 'deep3-2026-09-24'. Those two are not counted.
-- Tables: FINANCE__FED_SEC_CLOSED_END_FUND_INFORMATION, FINANCE__FED_OCC_NATIONAL_BANKS, FINANCE__FED_SEC_EDGAR_FINANCIALS, FINANCE__FED_FEC_COMMITTEES_DIM, FINANCE__FED_FEC_CAND_CMTE_LINKAGE.
-- 18 statements (S01-S18), all below in run order. S01 failed in the Python driver (year-0001 dates) and is counted; S09 re-ran it with the date as text.
-- Extracts (S01-S09) were analysed locally in pandas: g29/an_*.py. Outputs: g29/out_Sxx.txt / .csv / .pkl. Runner: g29/run.py.

-- S01 Closed-end funds: pull whole table (973 rows)  [ERROR: 252005: Failed to convert current row, cause: ordinal must be >= 1]
SELECT * FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_CLOSED_END_FUND_INFORMATION;

-- S02 OCC national banks: pull whole table (724 rows)  [724 rows, 0.5s, qid 01c74b9f-040b-a028-0026-eed30133d7a2]
SELECT * FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_OCC_NATIONAL_BANKS;

-- S03 SEC EDGAR financials: pull whole table (55.6K rows)  [55635 rows, 2.8s, qid 01c74b9f-040b-a770-0026-eed301339d12]
SELECT * FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_EDGAR_FINANCIALS;

-- S04 FEC committees dim: pull whole table (44.4K rows)  [44398 rows, 2.6s, qid 01c74b9f-040b-a028-0026-eed30133d7a6]
SELECT * FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_COMMITTEES_DIM;

-- S05 FEC cand-cmte linkage: pull whole table (30.5K rows)  [30536 rows, 0.7s, qid 01c74b9f-040b-a770-0026-eed301339d16]
SELECT * FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_CAND_CMTE_LINKAGE;

-- S06 FEC PAC summary (join partner for the committees dim): pull whole table (45.7K rows)  [45709 rows, 1.2s, qid 01c74b9f-040b-a6f8-0026-eed30133ac7e]
SELECT * FROM LIBRARY_MARTS.POLITICS.POLITICS__FED_FEC_PAC_SUMMARY;

-- S07 POLITICS copy of the cand-cmte link (duplicate-table check for S05): pull whole table (16.2K rows)  [16229 rows, 0.6s, qid 01c74b9f-040b-a79a-0026-eed301338c7a]
SELECT * FROM LIBRARY_MARTS.POLITICS.POLITICS__FEC_CAND_CMTE_LINK;

-- S08 FDIC branch deposits, per bank cert across all survey years, only certs on the OCC list (join partner for S02)  [664 rows, 1.3s, qid 01c74ba0-040b-9feb-0026-eed30133c7c6]
WITH occ AS (SELECT DISTINCT TO_VARCHAR(CERT) cert FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_OCC_NATIONAL_BANKS WHERE CERT IS NOT NULL)
SELECT s.FDIC_CERT, MIN(s.SURVEY_YEAR) first_yr, MAX(s.SURVEY_YEAR) last_yr,
       SUM(IFF(s.SURVEY_YEAR = 2025, s.BRANCH_DEPOSITS_THOUSANDS, 0)) dep_2025,
       SUM(IFF(s.SURVEY_YEAR = 2020, s.BRANCH_DEPOSITS_THOUSANDS, 0)) dep_2020,
       COUNT_IF(s.SURVEY_YEAR = 2025) branches_2025,
       MAX(IFF(s.SURVEY_YEAR = 2025, s.INSTITUTION_ASSETS_THOUSANDS, NULL)) assets_2025,
       MAX(IFF(s.SURVEY_YEAR = 2025, s.SPECIALIZATION_GROUP_DESC, NULL)) spec_2025,
       MAX(IFF(s.SURVEY_YEAR = 2025, s.CHARTER_AGENCY, NULL)) chartag_2025,
       MAX(IFF(s.SURVEY_YEAR = 2025, s.HOLDING_COMPANY_NAME, NULL)) hc_2025,
       MIN(IFF(s.MAIN_OFFICE_FLAG IN ('1','Y','true'), s.SIMS_ESTABLISHED_DATE, NULL)) main_est
FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FDIC_SOD_BRANCH_DEPOSITS s
JOIN occ ON occ.cert = s.FDIC_CERT
GROUP BY 1;

-- S09 Closed-end funds: pull whole table again, FILING_DATE as text (S01 died on year-0001 dates in the Python driver)  [973 rows, 0.5s, qid 01c74ba5-040b-a07c-0026-eed30133e826]
SELECT FILE_NO, CIK, REGISTRANT_NAME, ADDRESS_1, ADDRESS_2, CITY, STATE, ZIP_CODE,
       TO_VARCHAR(FILING_DATE, 'YYYY-MM-DD') AS FILING_DATE_TXT, YEAR(FILING_DATE) AS FILING_YR, FILING_TYPE
FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_CLOSED_END_FUND_INFORMATION;

-- S10 Insider open-market sales (code S) per issuer per day, 2022-10 to 2025-06, only issuers in EDGAR_FINANCIALS (CIK compared as numbers)  [82027 rows, 1.7s, qid 01c74ba5-040b-a028-0026-eed30133d7ee]
WITH iss AS (SELECT DISTINCT TRY_TO_NUMBER(CIK) AS cik FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_EDGAR_FINANCIALS),
s AS (
  SELECT TRY_TO_NUMBER(sub.ISSUER_CIK) AS cik, t.TRANSACTION_DATE AS d, t.ACCESSION_NUMBER AS acc,
         t.SHARES, t.PRICE_PER_SHARE, t.TRANSACTION_VALUE
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_NONDERIV_TRANS t
  JOIN LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_SUBMISSION sub ON sub.ACCESSION_NUMBER = t.ACCESSION_NUMBER
  WHERE t.TRANSACTION_CODE = 'S' AND t.TRANSACTION_DATE BETWEEN '2022-10-01' AND '2025-06-30')
SELECT s.cik, s.d, COUNT(*) AS n_trades, COUNT(DISTINCT s.acc) AS n_forms,
       SUM(s.SHARES) AS shares, SUM(s.SHARES * s.PRICE_PER_SHARE) AS val_calc, SUM(s.TRANSACTION_VALUE) AS val_col,
       MAX(s.PRICE_PER_SHARE) AS max_px
FROM s JOIN iss ON iss.cik = s.cik
GROUP BY 1, 2;

-- S11 Insider tables coverage: trades per month (all issuers), how many land on a submission, share that are code S  [58 rows, 0.6s, qid 01c74ba5-040b-a911-0026-eed30134467e]
SELECT DATE_TRUNC('month', t.TRANSACTION_DATE) AS m, COUNT(*) AS trades, COUNT(sub.ACCESSION_NUMBER) AS on_submission,
       COUNT_IF(t.TRANSACTION_CODE = 'S') AS sales, COUNT(DISTINCT sub.ISSUER_CIK) AS issuers
FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_NONDERIV_TRANS t
LEFT JOIN LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_INSIDER_SUBMISSION sub ON sub.ACCESSION_NUMBER = t.ACCESSION_NUMBER
WHERE t.TRANSACTION_DATE BETWEEN '2021-01-01' AND '2026-12-31'
GROUP BY 1 ORDER BY 1;

-- S12 Duplicate-table check: EDGAR_FINANCIALS 2024 quarters vs the four DERA_SUB_2024Qx tables, by accession number  [8 rows, 0.4s, qid 01c74ba5-040b-a79a-0026-eed301338cde]
WITH dera AS (
  SELECT '2024q1' q, ADSH FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_DERA_SUB_2024Q1
  UNION ALL SELECT '2024q2', ADSH FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_DERA_SUB_2024Q2
  UNION ALL SELECT '2024q3', ADSH FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_DERA_SUB_2024Q3
  UNION ALL SELECT '2024q4', ADSH FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_DERA_SUB_2024Q4)
SELECT e.SOURCE_FILE, COUNT(*) AS edgar_rows, COUNT(dera.ADSH) AS in_dera, COUNT_IF(dera.q = e.SOURCE_FILE) AS same_quarter
FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_EDGAR_FINANCIALS e
LEFT JOIN dera ON dera.ADSH = e.ADSH
GROUP BY 1 ORDER BY 1;

-- S13 Harm join: EDGAR_FINANCIALS filers whose EIN matches a PBGC-trusteed pension plan sponsor (EIN padded to 9, 000000000 dropped)  [8 rows, 0.5s, qid 01c74ba5-040b-a5bb-0026-eed30133f71a]
WITH e AS (
  SELECT LPAD(REGEXP_REPLACE(EIN, '[^0-9]', ''), 9, '0') AS ein9, MAX(NAME) AS sec_name, MAX(CITYBA) AS sec_city, MAX(STPRBA) AS sec_st,
         MAX(FILED) AS last_filed, COUNT(*) AS filings
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_SEC_EDGAR_FINANCIALS
  WHERE REGEXP_REPLACE(EIN, '[^0-9]', '') NOT IN ('', '000000000')
  GROUP BY 1)
SELECT e.*, p.CASE_NUMBER, p.SPONSOR_NAME, p.PLAN_NAME, p.CITY AS pbgc_city, p.STATE AS pbgc_st,
       p.DATE_OF_PLAN_TERMINATION, p.DATE_OF_PBGC_TRUSTEESHIP, p.NUMBER_OF_PARICIPANTS_AT_DATE_OF_PLAN_TERMINATION AS participants
FROM e JOIN LIBRARY_MARTS.LABOR.LABOR__FED_PBGC_TRUSTEED_PLANS p
  ON LPAD(REGEXP_REPLACE(p.EIN, '[^0-9]', ''), 9, '0') = e.ein9
ORDER BY p.DATE_OF_PLAN_TERMINATION DESC;

-- S14 Verify the PAC-summary IE line against itemized Schedule E: IE dollars per spender per file cycle, superseded lines dropped (all spenders)  [4135 rows, 0.8s, qid 01c74ba7-040b-a07c-0026-eed30133e852]
SELECT SPE_ID, CYCLE_FILE, COUNT(*) AS lines, SUM(TRY_TO_NUMBER(EXP_AMO, 38, 2)) AS ie_amt,
       COUNT_IF(UPPER(COALESCE(IS_SUPERSEDED,'')) IN ('TRUE','1','Y')) AS superseded_lines
FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_INDEPENDENT_EXPENDITURES
WHERE UPPER(COALESCE(IS_SUPERSEDED,'')) NOT IN ('TRUE','1','Y')
GROUP BY 1, 2;

-- S15 Verify the contributions line against itemized committee-to-candidate money (pas2): per committee, cycle and transaction type, memo lines dropped  [10577 rows, 0.7s, qid 01c74ba7-040b-a79a-0026-eed301338d0a]
SELECT CMTE_ID, CYCLE, TRANSACTION_TP, COUNT(*) AS lines, SUM(TRANSACTION_AMT) AS amt
FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_COMMITTEE_TO_CANDIDATE
WHERE COALESCE(MEMO_CD,'') <> 'X'
GROUP BY 1, 2, 3;

-- S16 Donor profile for the 740 screened super PACs/hybrids: itemized individual gifts (deduped on committee+donor+ZIP5+date+amount, memo rows dropped), donors, retired donors, repeat donors  [2100 rows, 6.8s, qid 01c74ba7-040b-a5bb-0026-eed30133f742]
