  SELECT DISTINCT CMTE_ID, CYCLE_FILE, UPPER(TRIM(DONOR_NAME)) AS nm, LEFT(ZIP_CODE, 5) AS z, TRANSACTION_DATE AS d, TRANSACTION_AMT AS a,
