'C00863548','C00863944','C00864058','C00864926','C00865055','C00865352','C00865725','C00865923','C00866368','C00867036','C00867861','C00868448','C00868612','C00869487','C00870030','C00870584','C00870592','C00871079','C00871368','C00871988','C00872150','C00872655','C00873174','C00873232','C00874370','C00874503','C00874750','C00874834','C00875815','C00875856','C00876409','C00877027','C00877761','C00877787','C00878009','C00878652','C00878728','C00878801','C00879072','C00879221','C00879510','C00879908','C00880906','C00881805','C00881987','C00882050','C00882100','C00882399','C00882431','C00882944','C00883520','C00883785','C00884239','C00884510','C00884874','C00885707','C00886028','C00886614','C00886804','C00887141','C00887703','C00887851','C00887901','C00888800','C00889220','C00889246','C00889279','C00890020','C00890665','C00891135','C00891259','C00891275','C00891291','C00891325','C00891549')
    AND COALESCE(MEMO_CD, '') <> 'X' AND NOT COALESCE(IS_MEMO_TRANSACTION, FALSE)),
donor AS (SELECT CMTE_ID, CYCLE_FILE, nm, z, MAX(ret) AS ret, COUNT(*) AS gifts, SUM(a) AS amt FROM x GROUP BY 1, 2, 3, 4)
SELECT CMTE_ID, CYCLE_FILE, COUNT(*) AS donors, SUM(ret) AS retired_donors, SUM(gifts) AS gifts, SUM(amt) AS amt,
       COUNT_IF(gifts >= 10) AS donors_10plus, SUM(IFF(gifts >= 10, amt, 0)) AS amt_10plus, MEDIAN(amt) AS med_donor_total,
       SUM(IFF(ret = 1, amt, 0)) AS amt_retired
FROM donor GROUP BY 1, 2;

-- S17 Eyeball the join: every insider open-market sale inside an overdue window (report past its extended deadline), with owner, relationship, price  [217 rows, 0.7s, qid 01c74ba9-040b-a028-0026-eed30133d816]
WITH w AS (
  SELECT 1673481 AS cik, '2022-08-23'::date AS w0, '2023-05-21'::date AS w1, '10-Q 20220630' AS rpt
  UNION ALL SELECT 1673481 AS cik, '2022-11-23'::date AS w0, '2023-05-23'::date AS w1, '10-Q 20220930' AS rpt
  UNION ALL SELECT 1673481 AS cik, '2023-04-19'::date AS w0, '2023-06-14'::date AS w1, '10-K 20221231' AS rpt
  UNION ALL SELECT 1787412 AS cik, '2022-11-17'::date AS w0, '2023-06-01'::date AS w1, '10-K 20220731' AS rpt
  UNION ALL SELECT 1716583 AS cik, '2022-08-23'::date AS w0, '2023-04-30'::date AS w1, '10-Q 20220630' AS rpt
  UNION ALL SELECT 1716583 AS cik, '2022-11-23'::date AS w0, '2023-04-30'::date AS w1, '10-Q 20220930' AS rpt
  UNION ALL SELECT 1418100 AS cik, '2022-08-18'::date AS w0, '2023-09-07'::date AS w1, '10-Q 20220630' AS rpt
  UNION ALL SELECT 1787412 AS cik, '2023-06-23'::date AS w0, '2023-08-30'::date AS w1, '10-Q 20230430' AS rpt
  UNION ALL SELECT 1517022 AS cik, '2023-08-18'::date AS w0, '2023-08-27'::date AS w1, '10-Q 20230630' AS rpt
  UNION ALL SELECT 1698530 AS cik, '2023-11-23'::date AS w0, '2024-05-15'::date AS w1, '10-Q 20230930' AS rpt
  UNION ALL SELECT 1883085 AS cik, '2024-04-03'::date AS w0, '2024-04-24'::date AS w1, '10-K 20231231' AS rpt
  UNION ALL SELECT 1851860 AS cik, '2024-04-18'::date AS w0, '2024-09-19'::date AS w1, '10-K 20231231' AS rpt
  UNION ALL SELECT 1293971 AS cik, '2024-04-18'::date AS w0, '2024-09-12'::date AS w1, '10-K 20231231' AS rpt
  UNION ALL SELECT 1293971 AS cik, '2024-05-24'::date AS w0, '2024-09-12'::date AS w1, '10-Q 20240331' AS rpt
  UNION ALL SELECT 1702924 AS cik, '2024-04-18'::date AS w0, '2024-08-27'::date AS w1, '10-K 20231231' AS rpt
  UNION ALL SELECT 1702924 AS cik, '2024-05-24'::date AS w0, '2024-09-24'::date AS w1, '10-Q 20240331' AS rpt
  UNION ALL SELECT 91668 AS cik, '2024-07-24'::date AS w0, '2024-08-12'::date AS w1, '10-Q 20240531' AS rpt
  UNION ALL SELECT 1511820 AS cik, '2024-04-18'::date AS w0, '2024-07-09'::date AS w1, '10-K 20231231' AS rpt
  UNION ALL SELECT 1840225 AS cik, '2023-04-19'::date AS w0, '2023-10-31'::date AS w1, '10-K 20221231' AS rpt
  UNION ALL SELECT 1441082 AS cik, '2023-10-17'::date AS w0, '2023-10-22'::date AS w1, '10-K 20230630' AS rpt
  UNION ALL SELECT 899715 AS cik, '2023-03-20'::date AS w0, '2024-02-20'::date AS w1, '10-K 20221231' AS rpt
