  UNION ALL SELECT 1880613 AS cik, '2024-04-18'::date AS w0, '2024-10-14'::date AS w1, '10-K 20231231' AS rpt
  UNION ALL SELECT 1668370 AS cik, '2024-04-18'::date AS w0, '2024-12-22'::date AS w1, '10-K 20231231' AS rpt
  UNION ALL SELECT 834285 AS cik, '2022-11-18'::date AS w0, '2023-03-14'::date AS w1, '10-Q 20220930' AS rpt
